        int n=cars.size();
        vector<double> answer(n,-1);
        vector<int> stack;
        for(int i=n-1;i>=0;--i){
            while(!stack.empty()){
                int next=stack.back();
                if(cars[i][1]<=cars[next][1]){
                    stack.pop_back();
                    continue;
                }
                double time=(double)(cars[next][0]-cars[i][0])/(cars[i][1]-cars[next][1]);
                if(answer[next]<0||time<=answer[next]){
                    answer[i]=time;
                    break;
                }
                stack.pop_back();
            }
            stack.push_back(i);
        }
        return answer;
    }
